CREATE TABLE IF NOT EXISTS jurisdiction_areas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid NOT NULL REFERENCES continental_jurisdictions(id) ON DELETE CASCADE, parent_area_id uuid REFERENCES jurisdiction_areas(id) ON DELETE SET NULL, area_type text NOT NULL, area_code text NOT NULL, area_name text NOT NULL, geometry_json jsonb, status text NOT NULL DEFAULT 'Active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jurisdiction_domain_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid NOT NULL REFERENCES continental_jurisdictions(id) ON DELETE CASCADE, domain text NOT NULL, asset_type text, priority integer NOT NULL DEFAULT 100, framework_version_id uuid REFERENCES regulatory_framework_versions(id) ON DELETE SET NULL, required_authority text, approval_type text, source_reference text, status text NOT NULL DEFAULT 'Draft', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS asset_jurisdiction_resolutions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES continental_assets(id) ON DELETE CASCADE, jurisdiction_id uuid NOT NULL REFERENCES continental_jurisdictions(id), area_id uuid REFERENCES jurisdiction_areas(id), regulatory_domain text NOT NULL, asset_type text, resolution_status text NOT NULL DEFAULT 'Unresolved', applicable_framework_version_id uuid REFERENCES regulatory_framework_versions(id), authority_name text, approval_type text, blocker_reason text, evidence_reference text, resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_jurisdiction_areas_parent ON jurisdiction_areas(parent_area_id,area_type,status);
CREATE INDEX IF NOT EXISTS idx_domain_rules_lookup ON jurisdiction_domain_rules(jurisdiction_id,domain,asset_type,status,priority);
CREATE INDEX IF NOT EXISTS idx_asset_jurisdiction_asset ON asset_jurisdiction_resolutions(asset_id,regulatory_domain,resolution_status);